@layer index.tokens, index.base, index.components;

@layer index.components {
.ix-combobox-field { min-width: 240px; }

.ix-combobox-popup {
  min-width: var(--anchor-width);
  max-height: min(320px, var(--available-height));
  overflow: hidden;
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius-md);
  background: var(--ix-bg-flyout);
  box-shadow: var(--ix-shadow-flyout);
  color: var(--ix-ink);
  transform-origin: var(--transform-origin);
  transition: opacity var(--ix-enter-duration) var(--ix-ease-out, ease-out), transform var(--ix-enter-duration) var(--ix-ease-out, ease-out);
}

.ix-combobox-popup[data-starting-style],
.ix-combobox-popup[data-ending-style] { opacity: 0; transform: scale(0.98); }

.ix-combobox-popup:focus-visible,
.ix-combobox-item:focus-visible { outline: 0; }

.ix-combobox-list { padding: 4px; overflow-y: auto; }

.ix-combobox-item {
  display: flex;
  min-height: 30px;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 5px 7px;
  border-radius: 5px;
  color: var(--ix-ink-secondary);
  font-size: var(--ix-type-ui);
  outline: none;
  cursor: default;
}

.ix-combobox-item[data-highlighted] { background: var(--ix-hover); color: var(--ix-ink); }

.ix-combobox-item[data-disabled] { color: var(--ix-ink-disabled); }

.ix-combobox-item__indicator { display: grid; width: 14px; height: 14px; flex: 0 0 auto; place-items: center; }

.ix-combobox-item__indicator svg { width: 12px; height: 12px; }

.ix-combobox { display: flex; width: 100%; height: 32px; align-items: center; border: 1px solid var(--ix-border); border-radius: var(--ix-radius-sm); background: var(--ix-control-surface); box-shadow: var(--ix-shadow-control); transition: border-color var(--ix-hover-duration) ease, box-shadow var(--ix-hover-duration) ease; }

.ix-combobox:focus-within { border-color: var(--ix-border-strong); box-shadow: 0 0 0 3px rgb(28 28 30 / 0.08); }

.ix-combobox__input { min-width: 0; height: 100%; flex: 1; border: 0; outline: 0; background: transparent; padding: 0 6px 0 10px; color: var(--ix-ink); font: inherit; font-size: var(--ix-type-ui); }

.ix-combobox__input::placeholder { color: var(--ix-ink-tertiary); }

.ix-combobox__action { display: grid; width: 27px; height: 27px; flex: 0 0 auto; place-items: center; border: 0; border-radius: 5px; background: transparent; color: var(--ix-ink-tertiary); cursor: pointer; }

.ix-combobox__action svg { width: 13px; height: 13px; }

.ix-combobox-item > span:first-child { display: grid; gap: 1px; }

.ix-combobox-item strong { font-weight: 480; }

.ix-combobox-item small { color: var(--ix-ink-tertiary); font-size: var(--ix-type-metadata); }

.ix-combobox-empty { padding: 22px 12px; color: var(--ix-ink-tertiary); font-size: var(--ix-type-ui); text-align: center; }

@media (hover: hover) and (pointer: fine) {
.ix-combobox__action:hover { background: var(--ix-hover); color: var(--ix-ink); }

.ix-combobox:hover { border-color: var(--ix-border-strong); }
}

@media (prefers-reduced-motion: reduce) {
.ix-combobox-popup { transition-duration: 0.01ms; }
}

.ix-positioner { z-index: var(--ix-layer-flyout); }

.ix-field { display: grid; min-width: 0; gap: 6px; }

.ix-field__label { color: var(--ix-ink); font-size: 12px; font-weight: 550; }

.ix-field[data-invalid] .ix-field__control { border-color: var(--ix-control-border-hover); box-shadow: inset 3px 0 0 var(--ix-fg-default); }

.ix-field__description,
.ix-field__error { color: var(--ix-ink-tertiary); font-size: 11.5px; line-height: 1.45; }

.ix-field__error { color: var(--ix-fg-default); font-weight: 520; }

.ix-combobox-popup {
  scrollbar-color: var(--ix-scrollbar-thumb) transparent;
  scrollbar-width: thin;
}

.ix-combobox-popup::-webkit-scrollbar { width: 10px; height: 10px; }

.ix-combobox-popup::-webkit-scrollbar-track { background: transparent; }

.ix-combobox-popup::-webkit-scrollbar-thumb {
  border: 3px solid transparent;
  border-radius: 999px;
  background: var(--ix-scrollbar-thumb);
  background-clip: padding-box;
}

.ix-combobox-popup::-webkit-scrollbar-thumb:hover { background: var(--ix-scrollbar-thumb-hover); background-clip: padding-box; }

:root[data-theme="dark"] .ix-field__error { color: var(--ix-ink); }

.ix-combobox-item__indicator {
  opacity: 1;
  transform: scale(1);
  transition: opacity 140ms var(--ix-ease-out), transform 140ms var(--ix-ease-out);
}

@starting-style {
.ix-combobox-item__indicator {
    opacity: 0;
    transform: scale(.72);
  }
}

.ix-combobox__trigger svg {
  transform-origin: center;
  transition: transform 160ms var(--ix-ease-out);
}

.ix-combobox__trigger[data-popup-open] svg {
  transform: rotate(180deg);
}

.ix-combobox__action { transition: color var(--ix-hover-duration), background-color var(--ix-hover-duration), transform var(--ix-press-duration) var(--ix-ease-out); }

.ix-combobox__action:active { transform: scale(.9); }

@media (prefers-reduced-motion: reduce) {
.ix-combobox__trigger svg,
.ix-combobox-item__indicator { transition-duration: 0.01ms; }
}

.ix-combobox-popup { background: var(--ix-bg-flyout); }

@media (forced-colors: active) {
.ix-combobox-popup { scrollbar-color: auto; }
}

@media (prefers-reduced-motion: reduce) {
.ix-combobox-popup {
    transition-property: opacity;
    transition-duration: var(--ix-exit-duration);
  }

.ix-combobox-popup[data-starting-style],
.ix-combobox-popup[data-ending-style] { transform: none; }

.ix-combobox__action:active { transform: none; }

.ix-combobox__trigger svg,
.ix-combobox-item__indicator { transition-duration: 0.01ms; }
}
}
